-- 001115_update_cookies_page.up.sql
-- Refreshes the seeded 'cookies' legal page (000885) to match the §19
-- opt-in consent model shipped after that seed was written:
--   * adds jc_consent (the banner decision) and jc_guest (consent-gated
--     visitor id) to the cookie table — both were missing entirely;
--   * corrects jc_journey_token duration 90 days → 30 days
--     (feed.guestJourneyTTL is 30d);
--   * adds the "With consent" category and points "Managing cookies" at
--     the #cookie-settings banner reopen instead of browser settings only.
-- Block ids are preserved so anchors/diffs stay meaningful.
-- The UPDATE is guarded on the stale '90 days' claim still being present,
-- so a cookies page already rewritten by an admin is left untouched.
--
-- Ref: .jeos/sections/19-gdpr-ndpr-compliance.md (Cookie Consent Mechanism)

BEGIN;

UPDATE pages SET
    blocks = '[{"id": "cookies-h", "type": "heading", "visible": true, "props": {"text": "Cookie Policy", "level": "h1", "size": "2xl", "align": "center", "eyebrow": "Legal", "subheading": "Last updated: November 11, 2026 · A short list, because we use few cookies."}}, {"id": "cookies-media", "type": "media", "visible": true, "props": {"media": {"media_id": "", "url": "/illustrations/cookies.svg", "alt": "Illustration of a cookie with a settings gear"}, "layout": "contained", "lightbox": false}}, {"id": "cookies-intro", "type": "content", "visible": true, "props": {"html": "\n<p>Cookies are small text files a site stores on your device. Japa.to uses a deliberately small set — enough to keep you signed in, keep the site secure, and remember your preferences. We do not use advertising trackers or third-party profiling cookies.</p>\n<h2>Cookies we set</h2>\n", "prose_style": "article"}}, {"id": "cookies-table", "type": "table", "visible": true, "props": {"columns": [{"key": "name", "label": "Cookie"}, {"key": "category", "label": "Category"}, {"key": "purpose", "label": "Purpose"}, {"key": "duration", "label": "Duration"}], "rows": [{"name": "jc_token", "category": "Strictly necessary", "purpose": "Your signed-in session", "duration": "Short-lived; renewed automatically"}, {"name": "jc_refresh", "category": "Strictly necessary", "purpose": "Securely refreshes your session", "duration": "Up to 30 days"}, {"name": "csrf_token", "category": "Strictly necessary", "purpose": "Protects actions from cross-site forgery", "duration": "Session"}, {"name": "jc_consent", "category": "Preferences", "purpose": "Remembers your cookie consent decision so we honour it", "duration": "1 year"}, {"name": "jc_theme", "category": "Preferences", "purpose": "Remembers light/dark/system appearance", "duration": "1 year"}, {"name": "jc_locale", "category": "Preferences", "purpose": "Remembers your language", "duration": "1 year"}, {"name": "nav_pin_override", "category": "Preferences", "purpose": "Remembers your nav rail preference", "duration": "1 year"}, {"name": "jc_journey_token", "category": "Preferences", "purpose": "Keeps guest checklist/assessment progress", "duration": "30 days"}, {"name": "jc_pwa_banner", "category": "Preferences", "purpose": "Remembers you dismissed the app-install prompt", "duration": "90 days"}, {"name": "jc_guest", "category": "With consent", "purpose": "Anonymous visitor identity for guest features — set only after you choose \"Accept all\"", "duration": "1 year"}], "sortable": false, "striped": true}}, {"id": "cookies-body", "type": "content", "visible": true, "props": {"html": "\n<h2>Categories explained</h2>\n<ul>\n  <li><strong>Strictly necessary</strong> — the Service cannot work without these. They cannot be switched off.</li>\n  <li><strong>Preferences</strong> — remember choices like theme and language. The site still works without them; it just won''t remember you.</li>\n  <li><strong>With consent</strong> — set only after you choose \"Accept all\" on the consent banner. Choosing \"Necessary only\" — or withdrawing later — deletes them on the next visit.</li>\n  <li><strong>Analytics</strong> — we use privacy-friendly, aggregate analytics to understand which features help people. Where analytics run, they do not use cross-site tracking cookies or build individual advertising profiles.</li>\n</ul>\n<h2>What we do not use</h2>\n<ul>\n  <li>No third-party advertising or retargeting cookies.</li>\n  <li>No social-media tracking pixels.</li>\n  <li>No sale of cookie-derived data to brokers.</li>\n</ul>\n<h2>Managing cookies</h2>\n<p>Use <a href=\"#cookie-settings\">Cookie settings</a> at any time to reopen the consent banner and change your decision — withdrawing is as easy as consenting. You can also block or delete cookies in your browser settings; blocking strictly-necessary cookies signs you out and parts of the site stop working.</p>\n<p>Browser-level \"Do Not Track\" signals are respected for analytics where the browser sends one.</p>\n<h2>Changes</h2>\n<p>If we add a new cookie category we will update this page and, where required, ask for consent first. Questions: <a href=\"/contact\">contact us</a> or see the <a href=\"/privacy\">Privacy Policy</a>.</p>\n", "prose_style": "article"}}, {"id": "cookies-cta", "type": "cta_banner", "visible": true, "props": {"headline": "Prefer fewer cookies?", "subhead": "Reopen the consent banner any time from Cookie settings in the footer — or manage data export and deletion in Settings.", "ctas": [{"label": "Open Settings", "href": "/settings", "variant": "primary"}, {"label": "Privacy Policy", "href": "/privacy", "variant": "ghost"}], "alignment": "center"}}]'::jsonb,
    meta = jsonb_set(COALESCE(meta, '{}'::jsonb), '{description}', '"Which cookies Japa.to sets, what each does, and how to manage or withdraw consent."'::jsonb),
    updated_at = now()
WHERE slug = 'cookies'
  AND page_type = 'page'
  AND status = 'published'
  -- Containment check on the stale 90-day journey row — structural, so it
  -- is immune to jsonb key-order/whitespace normalization, and it leaves
  -- an admin-rewritten cookies page untouched.
  AND blocks @> '[{"props": {"rows": [{"name": "jc_journey_token", "duration": "90 days"}]}}]'::jsonb;

COMMIT;
